-- LF núcleo S2: juicios Claude independientes, promoción únicamente AUTO, puente por intención.
-- No modificar lector IG, registros legados ni deprecaciones; una migración, un PR Train.
BEGIN;
DO $s2$
DECLARE p jsonb; cd text; hp text; h text; ev jsonb; juicio jsonb; promo jsonb;
  prev_eval record; before_legacy jsonb; before_deprec jsonb;
  n int:=0; promoted int:=0; manual int:=0; blocked int:=0; linked int:=0; v_estado text; residual text;
BEGIN
 SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO before_legacy FROM lf_ops.reglas r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO before_deprec FROM lf_ops.nucleo_deprecaciones r;
 IF (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='VIGENTE')<>64
 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>12
 OR (SELECT count(*) FROM lf_ops.lf_nucleo_cobertura_legada)<>80
 OR (SELECT count(distinct legacy_id) FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA')<>46
 OR (SELECT count(*) FROM lf_ops.reglas) NOT IN (215,586)
 OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
 THEN RAISE EXCEPTION 'S2_BASELINE_DRIFT'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements('[{"codigo":"S2-C01","version":1,"eval_id":299,"hash_paquete_atestado":"f8e362ae9f40a62ef030189a4de7b8e7fdf890df5e6b6569b9dd682e6b571239","veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:02 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":0.9,"observacion":"La regla no precisa el caso con cooldown ya vencido; queda modelado dentro del hecho violación."},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legacy_id":19,"estado_cobertura_esperado":"PARCIAL","diferencias":"La regla núcleo bloquea continuidad OTP ante violación agregada. No exige explícitamente que el OTP agotado cambie a inválido y que la sesión permanezca reutilizable tras el primer agotamiento; AUTH/OTP_MAX_ATTEMPTS y AUTH/OTP_EXHAUSTION_COOLDOWN_SECONDS se interpretan por backend.","residual":"Queda exigir invalidación física del OTP agotado, cooldown de seguridad completo y condición de primer agotamiento sin bloqueo permanente, independientemente del solo intento de continuar."},{"codigo":"S2-C02","version":1,"eval_id":300,"hash_paquete_atestado":"121373d073a9bf4a1a9060ac128e0c8ecaa58772dc10937e67d358169ef94976","veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:02 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":0.8,"observacion":"La expresión «o se intenta reanudar la misma sesión» admite dos lecturas y debe precisarse en la siguiente revisión."},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.8,"observacion":"Solapa protección por reenvíos con M4-B06 y con S2-C01; el agotamiento final y bloqueo definitivo delimita la intención."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legacy_id":20,"estado_cobertura_esperado":"REEMPLAZADA","diferencias":"El núcleo bloquea continuación y reanudación de la misma sesión tras agotar el último OTP reenviado; la legada exige estado BLOCKED y reiniciar ONB_001. El efecto BLOQUEAR no acredita transición física ni handler, sin diferencia de intención final verificada.","residual":""},{"codigo":"S2-C03","version":1,"eval_id":301,"hash_paquete_atestado":"e15752e0566e2a6727c8d8a547a0bf0eef562268fa109b94f9afed20c12b1225","veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:02 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"Cercana a M4-B07; la diferencia es bloqueo de campo y nueva sesión de REG_SEG_005, no aviso de soporte de REG_RL_003."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legacy_id":23,"estado_cobertura_esperado":"REEMPLAZADA","diferencias":"El núcleo impide cambio de celular sobre límite AUTH/PHONE_UPDATE_MAX_PER_SESSION; la legada además exige bloquear visualmente el campo e iniciar nueva sesión. El predicado agrega esas violaciones; no atribuye el mensaje de soporte propio de M4-B07.","residual":""},{"codigo":"S2-C04","version":1,"eval_id":302,"hash_paquete_atestado":"234b2d93a9dfd95441c7ff0801c1d0728b1dd1089d15bc282448dcc099b05428","veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:02 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":0.8,"observacion":"Política vigente sin versión fijada; binding de política rate limit de backend permanece pendiente."},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"Cercana a S2-C07, pero aplica OTP backend y no a políticas B2B operativas."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legacy_id":127,"estado_cobertura_esperado":"PARCIAL","diferencias":"El núcleo demanda rate limiting independiente del frontend por session_id e IP, pero no garantiza equivalencia de cuotas backend de la legada ni versión de política. Se refiere a lf_ops.politicas_rate_limit en lugar de límites incrustados.","residual":"Quedan verificar cuotas y ventanas de rate limiting en políticas backend independientes por session_id e IP y su binding; el contrato original no queda cubierto por el hecho lógico."},{"codigo":"S2-C05","version":1,"eval_id":303,"hash_paquete_atestado":"459e62449016a18bbb4d91ea19bb84cbd06d7c079868671b1cc3b0a1be0ddb5b","veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:02 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legacy_id":139,"estado_cobertura_esperado":"REEMPLAZADA","diferencias":"La legada históricamente indica JWT en cookie, aclarada como access token en memoria + refresh token cookie httpOnly/Secure/SameSite con PKCE; el núcleo adopta la aclaración más reciente y bloquea localStorage/sessionStorage.","residual":""},{"codigo":"S2-C06","version":1,"eval_id":304,"hash_paquete_atestado":"fb3dfd5b2886919c522f722887d69e3c424cfa2519daa65a1d9697d1d3238430","veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:02 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":0.9,"observacion":"Listas locales de perfiles es concepto poco acotado; la regla no debe sustituir política central MFA."},"CAL_ACCIONABLE":{"puntaje":0.8,"observacion":"Requiere tipificar como lista local cualquier matriz hardcodeada de perfiles o factores fuera de política central."},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legacy_id":398,"estado_cobertura_esperado":"REEMPLAZADA","diferencias":"La legada exige MFA y step-up por políticas centrales; núcleo bloquea decisión basada en matrices locales. Diferencia técnica: listas locales representan configuración hardcodeada y no referencias vigentes a políticas MFA.","residual":""},{"codigo":"S2-C07","version":1,"eval_id":305,"hash_paquete_atestado":"eabc82d7d97d9e25cd8e94985db879c773628a4fa09cfba0492ef0a846c9b88c","veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:02 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.8,"observacion":"Cercana a S2-C04; esta gobierna B2B rate limits por política central, no endpoint OTP."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legacy_id":418,"estado_cobertura_esperado":"REEMPLAZADA","diferencias":"La legada exige política lf_ops.politicas_rate_limit vía rate_limit_policy_id; núcleo bloquea máximos, ventanas y burst hardcodeados. Se limita a B2B; distinto de OTP backend en S2-C04.","residual":""},{"codigo":"S2-C08","version":1,"eval_id":306,"hash_paquete_atestado":"cdbe997aab8ab48704ac77a2972cc4516785887412f9703344d64951c36742ae","veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:02 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":0.8,"observacion":"Expresión «sin riesgo/señal de fallo» combina ausencia de riesgo y ausencia de fallo del invisible."},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legacy_id":429,"estado_cobertura_esperado":"REEMPLAZADA","diferencias":"La legada exige anti-bot invisible por defecto y visible solo tras riesgo o fallo; núcleo expresa ambos casos como bloqueo de desafío innecesario o ausencia de protección. Proveedor permanece agnóstico.","residual":""},{"codigo":"S2-C09","version":1,"eval_id":307,"hash_paquete_atestado":"331beef3aad99451002cd6147638245622bc25c7ab6cc403de4a3e0a1296ef60","veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:02 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legacy_id":432,"estado_cobertura_esperado":"REEMPLAZADA","diferencias":"La legada permite IdP confiable detrás de LF_AUTH_BOUNDARY server-side; núcleo bloquea credenciales verificadas en navegador y sesión sin validación en servidor. No se selecciona endpoint OIDC.","residual":""},{"codigo":"S2-C10","version":1,"eval_id":308,"hash_paquete_atestado":"b985a103398b5ef5552608e744309e8d6e2d6a9601aeaba4787af88e50ba7639","veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:02 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.8,"observacion":"error_id también aparece en S2-C11; S2-C10 es autoridad del mapeo proveedor a outcome y catálogo, no contrato de exposición externa."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legacy_id":433,"estado_cobertura_esperado":"REEMPLAZADA","diferencias":"La legada exige traducción única del proveedor a outcome estable y error_id del catálogo; S2-C10 posee autoridad exclusiva de asignación de error_id y resolución HTTP/mensaje por catálogo. S2-C11 solo verifica estructura de respuesta.","residual":""},{"codigo":"S2-C11","version":1,"eval_id":309,"hash_paquete_atestado":"9a2408c36eb3b7d0f648d282ca324940bc65202a45fe6c265fad7b3c33e3e9fe","veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:02 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":0.9,"observacion":"S2-C11 combina reglas de mínima respuesta y reference error_id; delimitar consumidor de la salida y origen."},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.8,"observacion":"S2-C10 genera outcome/error_id canónico; S2-C11 únicamente verifica que respuesta de LF_AUTH_BOUNDARY lo conserve, no define una segunda asignación."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legacy_id":436,"estado_cobertura_esperado":"REEMPLAZADA","diferencias":"La legada exige respuesta mínima con outcome, correlation_id, error_id cuando proceda y exclusión de datos sensibles; S2-C11 valida el uso del error_id producido por S2-C10, sin asignar ni mapear error_id nuevo.","residual":""},{"codigo":"S2-C12","version":1,"eval_id":310,"hash_paquete_atestado":"dfe0babd39b3c1bd579c78288a5b0aa18e1835df08d87b3d692229836b7a6093","veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:02 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legacy_id":437,"estado_cobertura_esperado":"REEMPLAZADA","diferencias":"La legada exige MFA_REQUIRED sin crear sesión AUTHENTICATED para usuarios con política MFA; núcleo bloquea acceso antes del segundo factor, sin fijar cantidad de perfiles ni proveedor.","residual":""}]'::jsonb) LOOP
  cd:=p->>'codigo';
  SELECT hash INTO h FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA';
  IF h IS NULL OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8
    THEN RAISE EXCEPTION 'S2_VERSION_TESTS_DRIFT %',cd; END IF;
  SELECT id,hash_paquete,decision INTO prev_eval FROM lf_ops.nucleo_evaluaciones
   WHERE regla=cd AND version=1 ORDER BY id DESC LIMIT 1;
  IF prev_eval.hash_paquete IS DISTINCT FROM p->>'hash_paquete_atestado'
   OR ((SELECT count(*) FROM lf_ops.reglas)=586 AND prev_eval.id IS DISTINCT FROM (p->>'eval_id')::bigint)
  THEN RAISE EXCEPTION 'S2_EVALUACION_DRIFT % id=%',cd,prev_eval.id; END IF;
  hp:=lf_ops.nucleo_hash_paquete_v1(cd,1);
  IF hp IS DISTINCT FROM p->>'hash_paquete_atestado' THEN
   RAISE EXCEPTION 'S2_HASH_DRIFT %',cd; END IF;
  juicio:=jsonb_build_object('regla',cd,'hash_evaluado',hp,'veredicto','PASS',
   'puntajes',p->'puntajes','juez',p->>'juez','modo','INDEPENDIENTE',
   'revisor_es_productor',false,'llamadas_modelo',1,
   'evidencia_ref','sandbox/lf_contract_gate_test/nucleo_ci/nucleo_juicios_independientes_s2_v1.json#'||cd);
  BEGIN
    PERFORM lf_ops.nucleo_juicio_registrar_v1(juicio||jsonb_build_object('hash_evaluado',repeat('0',64)));
    RAISE EXCEPTION 'S2_HASH_NEGATIVE_ACCEPTED %',cd;
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF;
  END;
  PERFORM lf_ops.nucleo_juicio_registrar_v1(juicio);
  ev:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
  IF ev->>'decision'='AUTO' THEN
    promo:=lf_ops.nucleo_regla_promover_v1(cd);
    IF promo->>'resultado'<>'PROMOVIDA_AUTO' THEN RAISE EXCEPTION 'S2_PROMOTION_FAILED % %',cd,promo; END IF;
    SELECT estado INTO v_estado FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1;
    IF v_estado<>'PUBLICADA' THEN RAISE EXCEPTION 'S2_PUBLICATION_NOT_VERIFIED %',cd; END IF;
    residual:=p->>'residual';
    IF p->>'estado_cobertura_esperado'='PARCIAL' AND length(btrim(residual))<15
       THEN RAISE EXCEPTION 'S2_PARTIAL_WITHOUT_RESIDUAL %',cd; END IF;
    INSERT INTO lf_ops.lf_nucleo_cobertura_legada
     (legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
    VALUES
     ((p->>'legacy_id')::int,cd,1,p->>'estado_cobertura_esperado',p->>'diferencias',
      jsonb_build_object('fuente','lf_ops.v_reglas_compat_v1/'||(p->>'legacy_id')||' juez atestado 2026-11-23 21:02 Lima',
       'contraste','LEGADA '||(SELECT descripcion FROM lf_ops.v_reglas_compat_v1 WHERE id=(p->>'legacy_id')::int)
        ||' NUCLEO PUBLICADO '||(SELECT descripcion FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1)
        ||' DIFERENCIA '||(p->>'diferencias'),
       'residual',residual,'juicio','CLAUDE_INDEPENDIENTE','distincion_C10_C11',
        CASE WHEN cd='S2-C10' THEN 'C10: asigna outcome y error_id desde catálogo; es el único mapeador'
             WHEN cd='S2-C11' THEN 'C11: verifica salida ya normalizada sin segunda asignacion de error_id' ELSE '' END),
       hp,'GPT-6 entrada de juicio atestada por Claude');
    promoted:=promoted+1;linked:=linked+1;
  ELSIF ev->>'decision'='MANUAL' THEN manual:=manual+1;
  ELSE blocked:=blocked+1; END IF;
  n:=n+1;
  RAISE NOTICE 'S2_RUN cd=% nota=% decision=% juicio_hash=%',cd,ev->>'nota',ev->>'decision',hp;
  promo:=null;
 END LOOP;
 IF n<>12 OR n<>promoted+manual+blocked
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.reglas r) IS DISTINCT FROM before_legacy
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones r) IS DISTINCT FROM before_deprec
 OR (SELECT count(*) FROM lf_ops.nucleo_juicios WHERE regla LIKE 'S2-C%')<>12
 OR (SELECT count(*) FROM lf_ops.lf_nucleo_cobertura_legada WHERE nucleo_codigo LIKE 'S2-C%')<>linked
 THEN RAISE EXCEPTION 'S2_FINAL_GUARD'; END IF;
 RAISE NOTICE 'S2_PASS judged=% auto=% manual=% blocked=% links=% no_legacy_edits',n,promoted,manual,blocked,linked;
END $s2$;
COMMIT;
